KB, DT, DC = 5, 4, 3
N_TR, N_UN = 80, 40
N_CTX, N_CTX_TR = 16, 12
D_E, D_C, D_DIS = 48, 16, 8
D_IN = 2 * D_E + D_C + D_DIS                  # self token, partner token, context, distractor
ID_DIMS = list(range(32, 48)) + list(range(D_E + 32, D_E + 48))
